"""Deterministic business briefs. No AI API or runtime generation service."""
import re
from html import escape

PROFILES = {
 'hotel': ('A place to slow down.', 'Thoughtful stays, made around you.', ['Comfortable rooms', 'Dining & relaxation', 'Plan your stay']),
 'auto': ('Keep moving. With confidence.', 'Care for your vehicle, without the guesswork.', ['Maintenance', 'Diagnostics', 'Repairs']),
 'spa': ('Make room for yourself.', 'A quieter moment. A little more balance.', ['Massage', 'Wellness treatments', 'Relaxation']),
 'business': ('Good work. Personal attention.', 'Discover what we can do for you.', ['Our services', 'Personal consultation', 'Ongoing support']),
}

def describe_website(description):
    description = description.strip()
    if not 20 <= len(description) <= 5000:
        raise ValueError('Describe your website in 20–5,000 characters.')
    lower = description.casefold()
    groups = [('hotel', r'\b(hotel|resort|accommodation|inn|lodge)\b'), ('auto', r'\b(auto\s*shop|car\s*repair|automotive|garage|talyer|mekaniko)\b'), ('spa', r'\b(spa|massage|wellness|hilot|masahe)\b')]
    kind = next((name for name, pattern in groups if re.search(pattern, lower)), 'business')
    def field(label):
        match = re.search(r'(?im)^\s*(?:'+label+r')\s*:\s*(.+)$', description)
        return match.group(1).strip() if match else ''
    services = field('services|serbisyo|rooms|treatments')
    accent = next((value for word, value in [('purple','#7554a3'),('blue','#326b97'),('red','#a33e3e'),('green','#48745b'),('gold','#997940'),('teal','#357f7a')] if re.search(r'\b'+word+r'\b',lower)), {'hotel':'#917043','auto':'#b45435','spa':'#567963','business':'#426e8b'}[kind])
    brief = {'kind':kind,'description':description,'name':field('name|business name|pangalan'), 'location':field('location|address|lokasyon'), 'email':field('email'), 'phone':field('phone|telephone|contact number'), 'services':[s.strip() for s in re.split('[,;]',services) if s.strip()][:9] or PROFILES[kind][2], 'accent':accent,'dark':bool(re.search(r'\bdark\b',lower))}
    return {'site':{'title':brief['name'] or 'Your business'},'blueprint':{'layout_kind':'business_brief','authored_template':True,'brief':brief},'notes':['Description mapped to a deterministic business template. Custom requirements outside the supported fields are retained in the brief, not automatically implemented.']}


def render_business(analysis, project_name):
    brief = analysis['blueprint']['brief'];kind = brief['kind'];headline, subtitle, _ = PROFILES[kind]
    name = escape(brief['name'] or project_name or 'Your business')
    services = ''.join('<article><span>0'+str(i+1)+'</span><h3>'+escape(s)+'</h3><a href="#contact">Ask about this service ↗</a></article>' for i,s in enumerate(brief['services']))
    contact=''
    for label in ['location','email','phone']:
        if brief[label]:contact+='<p><strong>'+label.title()+'</strong><br>'+escape(brief[label])+'</p>'
    if not contact:contact='<p>Add your business contact details to make it easy for visitors to reach you.</p>'
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+name+'''</title><link rel="stylesheet" href="style.css"></head><body><nav><a class="brand" href="#">'''+name+'''<span>✳</span></a><button id="menu" aria-expanded="false" aria-controls="links">Menu</button><div id="links"><a href="#services">What we offer</a><a href="#about">Our approach</a><a href="#contact">Get in touch ↗</a></div></nav><main><section class="hero"><div><p class="eyebrow">'''+escape(brief['location'] or 'WELCOME TO '+(brief['name'] or project_name or 'YOUR BUSINESS'))+'''</p><h1>'''+headline+'''</h1><p class="intro">'''+subtitle+'''</p><a class="cta" href="#services">Explore what we offer ↗</a><p class="small">A thoughtful experience, from the first hello.</p></div><div class="art '''+kind+'''" aria-label="Original decorative illustration"><div class="sun"></div><div class="arch"></div><div class="shape"></div><span class="art-label">'''+name+'''<br><small>EVERY DETAIL MATTERS</small></span></div></section><section id="services"><p class="eyebrow">MADE AROUND YOUR NEEDS</p><h2>A better everyday experience.</h2><div class="services">'''+services+'''</div></section><section id="about" class="about"><span>✧</span><div><p class="eyebrow">A PERSONAL APPROACH</p><h2>Small details.<br>A meaningful difference.</h2><p>Explore our services and get in touch to discuss what you need. We believe a clear conversation is the best place to start.</p></div></section><section id="contact"><p class="eyebrow">LET’S START A CONVERSATION</p><h2>We’d love to hear from you.</h2><div class="contact">'''+contact+'''</div></section></main><footer>'''+name+'''<a href="#">Back to top ↑</a></footer><script src="app.js"></script></body></html>'''
    css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:15px Segoe UI,Arial,sans-serif}a{color:inherit;text-decoration:none}button{font:inherit;cursor:pointer}nav{display:flex;justify-content:space-between;align-items:center;padding:27px 6%;border-bottom:1px solid var(--line);gap:20px}.brand{font-size:21px;font-weight:650;overflow-wrap:anywhere}.brand span{color:var(--accent);margin-left:12px}#links{display:flex;gap:30px;font-size:12px}#menu{display:none}main{max-width:1400px;margin:auto;padding:0 6%}.hero{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center;padding:75px 0}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--accent);text-transform:uppercase}h1{font:clamp(44px,5.8vw,79px)/1.02 Georgia,serif;letter-spacing:-2px;margin:25px 0}h2{font:clamp(30px,4vw,47px)/1.15 Georgia,serif;font-weight:400;letter-spacing:-1px}.intro{font-size:17px;line-height:1.8;opacity:.7;max-width:340px}.cta{display:inline-block;background:var(--accent);color:white;padding:15px 23px;border-radius:5px;margin-top:22px;font-size:12px}.small{font-size:10px;opacity:.5;margin-top:20px}.art{height:490px;border-radius:160px 160px 10px 10px;position:relative;overflow:hidden;background:linear-gradient(140deg,#dedac5,#a2b1a1)}.sun{position:absolute;top:50px;right:80px;border-radius:50%;width:110px;height:110px;background:#f4e6c2}.arch{position:absolute;bottom:0;left:15%;width:50%;height:65%;background:#667c6b;border-radius:140px 140px 0 0;box-shadow:20px 10px 0 #cad1bb}.shape{position:absolute;bottom:-110px;right:-30%;width:100%;height:350px;border-radius:50%;background:#3e5c4c}.art-label{position:absolute;bottom:35px;left:30px;color:#fff;font:24px Georgia,serif}.art-label small{font:8px Segoe UI,sans-serif;letter-spacing:2px}.auto{background:linear-gradient(150deg,#c6b9a3,#575e63);border-radius:8px}.auto .arch{border-radius:50%;height:260px;width:260px;left:20%;bottom:90px;background:#252c33;box-shadow:inset 0 0 0 50px #3a444c,0 20px 35px #0003}.auto .sun{height:180px;width:180px;background:#cf9e6f;right:-20px;top:40px}.auto .shape{background:#2c3940}.spa .arch{transform:rotate(-20deg);border-radius:50%;height:230px;bottom:40px;background:#8d9c7d}.spa .shape{background:#6a7c61}.services{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:32px}section{padding:50px 0;scroll-margin-top:25px}article{padding:28px;border:1px solid var(--line);border-radius:8px}article span{color:var(--accent);font:26px Georgia,serif}article h3{font-weight:550;font-size:19px;overflow-wrap:anywhere}article a{font-size:11px;opacity:.65}.about{display:grid;grid-template-columns:1fr 1.5fr;gap:40px;align-items:center;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-top:25px}.about>span{font-size:210px;text-align:center;color:var(--accent);opacity:.5}.about p:not(.eyebrow){max-width:430px;line-height:1.9;opacity:.65}.contact{display:flex;gap:45px;flex-wrap:wrap;line-height:1.8;overflow-wrap:anywhere}.contact strong{font-size:11px;color:var(--accent)}footer{padding:30px 6%;display:flex;justify-content:space-between;border-top:1px solid var(--line);font-size:12px}a:hover{opacity:.75}:focus-visible{outline:3px solid var(--accent);outline-offset:4px}@media(max-width:800px){.hero{gap:30px;padding:45px 0}.art{height:380px}.services{grid-template-columns:1fr 1fr}.about>span{font-size:130px}}@media(max-width:550px){nav{flex-wrap:wrap}.brand{font-size:18px;max-width:75%}#menu{display:block;border:1px solid var(--line);color:inherit;background:none;border-radius:4px;padding:7px 10px}#links{display:none;width:100%;flex-direction:column;gap:15px}#links.open{display:flex}.hero{grid-template-columns:1fr;gap:35px}.art{height:340px}.services{grid-template-columns:1fr}.about{grid-template-columns:1fr;gap:0}.about>span{display:none}section{padding:35px 0}h1{font-size:53px}.contact{gap:15px}footer{gap:20px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
    css=':root{--accent:'+brief['accent']+';--bg:'+('#17201e' if brief['dark'] else '#faf8f2')+';--ink:'+('#f0eee6' if brief['dark'] else '#353f35')+';--line:'+('#39433d' if brief['dark'] else '#e2e4d9')+'}'+css
    js="const menu=document.getElementById('menu'),links=document.getElementById('links');menu.onclick=()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));};links.onclick=()=>{links.classList.remove('open');menu.setAttribute('aria-expanded','false');};"
    return html,css,js
